head.script:
scwin.vScrenID = "ULDFIS00301.xml";

scwin.onpageload = function() {
    scwin.fn_Init();
};
/**
 *  화면 초기화
 */
scwin.fn_Init = function() {
    //패널 라운드 처리
    //$c.cm.PanelToGroupBox(panel_Top);

    //라디오 기본값 : 사업목적
    rdo_fg.setValue("01");

    // rdo_Fg 값에따른 화면 처리
    scwin.fn_RdoFgOnSelChange();

    // 기업코드 hidden처리 
    ibx_KisCd.hide();
};


/**
 *  라디오 OnSelChange
 */
scwin.fn_RdoFgOnSelChange = function() {

    let pageNum = rdo_fg.getValue();

    if (pageNum == "01" || pageNum == "03" || pageNum == "04" || pageNum == "05" || pageNum == "06" || pageNum == "07" || pageNum == "11") {
        btn_Excel.setStyle("visibility","visible"); 
    } else {
        btn_Excel.setStyle("visibility","hidden");
    }
    // 라디오 클릭 시 하단 프레임에 적당한 화면 세팅.
    scwin.fn_DisplayFrame(pageNum);


    // 결산일자 visible
    scwin.fn_DisplayAcntclsDt();


};


/**
 *  하단 frome에 화면 표시
 */
scwin.fn_DisplayFrame = function(pVal) {
    $p.parent().wfm_body.setSrc(scwin.fn_GetUrl(String(Number(pVal) + 1 ).padStart(2,"0")));

};


/**
 *  url 만들기
 */
scwin.fn_GetUrl = function(pVal) {
    var vUrl = "/ui/lst/fis/ULDFIS003" + pVal + ".xml";
    return vUrl;
};


/**
 * 결산일자 visible
 */
scwin.fn_DisplayAcntclsDt = function() {
    // 주요주주, 배당, 관계회사현황
    if (rdo_fg.getValue() == "02" || rdo_fg.getValue() == "04" || rdo_fg.getValue() == "08" || rdo_fg.getValue() == "09" ||
        rdo_fg.getValue() == "10") {
        $c.stf.showObj(grp_AcntclsDt, true);
    } else {
        $c.stf.showObj(grp_AcntclsDt, false);
    }

};



/**
 *  결산일자 검색
 */
scwin.fn_SrchAcntclsDt = async function() {
    //데이터셋 초기화
    scwin.fn_InitDs("2");

    let reqMap = {
        kisCd: ibx_KisCd.getValue(), //기업코드
        fg: "02",
    };

    await $c.sbm.execute(sbm_dlt_AcntclsDtRes, reqMap);

    await $p.parent().wfm_body.getWindow().scwin.fn_Search();

    //$p.parent().wfm_body.getWindow().scwin.fn_Search(); // 하단 조회

};


/**
 *  조회조건 유효성 체크
 */
scwin.fn_ChkValid = function() {
    //필수항목 체크.
    if (ibx_CoSnm.getValue() == "") {
        alert("기업명을 입력하세요.");
        ibx_CoSnm.focus();
        return false;
    }

    if (grp_AcntclsDt.getStyle("display") == "block" && ibx_KisCd.getValue() == "" ) {
        alert("결산일자를 입력하세요.");
        sbx_AcntclsDt.focus();
        return false;
    }

    console.log("조회컴포넌트:: scwin.fn_ChkValid" + ibx_KisCd.getValue());
    // 기업명은 있는데 기업코드가 없는 경우
    if (ibx_CoSnm.getValue() != "" && ibx_KisCd.getValue() == "") {
        //scwin.fn_ComInfoSrch();
        return false;
    }
    return true;
};


/**
 * 개별주석사항 조히
 */
scwin.fn_Search = async function() {

    // 조회조건 필수 체크.
     if (!scwin.fn_ChkValid()) {
         return;
     }
   // wfm_body 자식 fn_search()호출   
      if($p.parent().wfm_body.getWindow().scwin.fn_Search) {
          if(grp_AcntclsDt.getStyle("display") != "none") { 
            await scwin.fn_SrchAcntclsDt();//결산일자 조회
          } else {
            await $p.parent().wfm_body.getWindow().scwin.fn_Search(); //개별주석조회
          }  
      }       


    //
};



/**
 *  데이터셋 초기화.
 */
scwin.fn_InitDs = function(pFg) {
    if (pFg == "1") {
        dts_ComInfo.removeAll();
    } else if (pFg == "2") {
        dlt_AcntclsDtRes.removeAll();
    }
};



/**
 * 기업정보 조회(명으로 조회)
 */
scwin.fn_ComInfoSrch = function(pWorkFg) {
    //데이터셋 초기화
    scwin.fn_InitDs("2");

    let reqMap = {
        coSnm: ibx_CoSnm.getValue(), //기업코드
    };
    $c.sbm.execute(sbm_comInfo, reqMap);
};


/**
 * 기업검색 팝업
 */
scwin.fn_ComSrchOpen = async function() {
    // await $c.frame.CreateDialogFrame("KIS_CD", "./ULDFIS00100_P1.gfm", "기업 검색", 100, 100, 640 + 20, 445 + 45, "window");
    // $c.cm.ins_popupOpen("KIS_CD", ibx_SRCH_ISUR_NM, "ULDFIS00101", "기업 검색", "550", "450");

    var url = "/ui/lst/fis/ULDFIS00101.xml";
    var popTitle = "기업 검색";

    const opts = {
        id: "ULDFIS00101",
        popupName: popTitle,
        width: 900,
        height: 679,
        frameModal: "top",
        // popupParam: {
            data: {
                coSnm: ibx_CoSnm.getValue(),
                kisCd: ibx_KisCd.getValue(),
                indPttn: ibx_indPttn.getValue(),
            },
            // callback: "fn_GetParKisCd",
        // },
    };

    const res = await $c.win.openPopup(url, opts);

    ibx_CoSnm.setValue(res.coSnm); //기업명
    ibx_KisCd.setValue(res.kisCd); //기업코드
    ibx_indPttn.setValue(res.indPttn); //업종유형

    // if (ibx_KisCd.getValue() != "") {
    //     scwin.fn_Search();
    // }
};


/**
 * 팝업으로 값을 넘김.
 */
scwin.fn_GetParKisCd = function() {
    var arrPar = new Array();
    arrPar[0] = ibx_CoSnm.getValue(); // 기업명
    return arrPar;
};


/**
 *  조회조건의 kisCd를 리턴.
 */
scwin.fn_GetKisCd = function() {

    return ibx_KisCd.getValue();
};


/**
 *  조회조건의 AcntclsDt를 리턴.
 */
scwin.fn_GetAcntclsDt = function() {
    return sbx_AcntclsDt.getValue();
};

scwin.rdo_Fg_OnSelChange = function() {
    // 라디오 클릭
    scwin.fn_RdoFgOnSelChange();
};

scwin.btn_Search_onclick = function() {
    // 조회버튼 클릭
    scwin.fn_Search();
};

scwin.img_CoSearch_onclick = function() {
    // 기업검색팝업 오픈
    scwin.fn_ComSrchOpen();
};

scwin.ibx_CoSnm_onkeydown = function(e) {
   // 기업명 키다운.
    if (e.keyCode == 13) { //Enter
        if (ibx_CoSnm.getValue() == "") {
            // 기업검색팝업 오픈
            scwin.fn_ComSrchOpen();
        } else {
            // 기업정보 조회
            scwin.fn_ComInfoSrch();
        }
    }
};

scwin.ibx_CoSnm_onchange = function() {
    console.log("scwin.ibx_CoSnm_onchange");
    // 조회조건이 변경된 경우 초기화.
    ibx_KisCd.setValue("");
};

scwin.btn_Excel_onclick = function() {
    if ($p.parent().wfm_body.getWindow().scwin.fn_excel_download) {
        $p.parent().wfm_body.getWindow().scwin.fn_excel_download();
    }
};

// 기업명 엔터후
scwin.sbm_comInfo_submitdone = async function (e) {
    dlt_comInfoRes.setJSON(e.responseJSON.body);
    // 조회결과가 1개이면 기업개황 조회 아니면 기업팝업 오픈.
    if (dlt_comInfoRes.getTotalRow() == 1) {
        // 조회조건에 값을 세팅하고..
        ibx_KisCd.setValue(dlt_comInfoRes.getCellData(0, "kisCd"));
        ibx_indPttn.setValue(dlt_comInfoRes.getCellData(0, "indPttn"));

        await scwin.fn_SrchAcntclsDt();//결산일자 조회
        //scwin.fn_Search(); // 개별주석 조회
        //await $p.parent().wfm_body.getWindow().scwin.fn_Search();

    } else {
        scwin.fn_ComSrchOpen(); //기업검색 팝업 오픈
    }
};


scwin.sbm_dlt_AcntclsDtRes_submitdone = function (e) {
    $p.parent().wfm_body.getWindow().scwin.fn_Search(); // 개별주석 조회
};
